"""Fourth curated tranche of materially distinct Python algorithms."""

ADVANCED_TASK_CODE_SPECS_4 = (
    ("postfix_expression", "Write a Python function that evaluates a whitespace-tokenized postfix expression containing integers and the operators +, -, *, and /, requiring exact integer division.", "def evaluate_postfix(tokens):\n    stack = []\n    for token in tokens:\n        if token not in {\"+\", \"-\", \"*\", \"/\"}:\n            stack.append(int(token))\n            continue\n        if len(stack) < 2:\n            raise ValueError(\"invalid postfix expression\")\n        right = stack.pop()\n        left = stack.pop()\n        if token == \"+\":\n            stack.append(left + right)\n        elif token == \"-\":\n            stack.append(left - right)\n        elif token == \"*\":\n            stack.append(left * right)\n        elif right == 0 or left % right:\n            raise ValueError(\"division must be exact and nonzero\")\n        else:\n            stack.append(left // right)\n    if len(stack) != 1:\n        raise ValueError(\"invalid postfix expression\")\n    return stack[0]"),
    ("infix_to_postfix", "Write a Python function that converts tokens from an infix expression containing operands, parentheses, and +, -, *, / operators into postfix order.", "def infix_to_postfix(tokens):\n    precedence = {\"+\": 1, \"-\": 1, \"*\": 2, \"/\": 2}\n    output = []\n    operators = []\n    for token in tokens:\n        if token == \"(\":\n            operators.append(token)\n        elif token == \")\":\n            while operators and operators[-1] != \"(\":\n                output.append(operators.pop())\n            if not operators:\n                raise ValueError(\"unbalanced parentheses\")\n            operators.pop()\n        elif token in precedence:\n            while operators and operators[-1] in precedence and precedence[operators[-1]] >= precedence[token]:\n                output.append(operators.pop())\n            operators.append(token)\n        else:\n            output.append(token)\n    while operators:\n        if operators[-1] == \"(\":\n            raise ValueError(\"unbalanced parentheses\")\n        output.append(operators.pop())\n    return output"),
    ("wildcard_matching", "Write a Python function that reports whether an entire string matches a pattern where `?` matches one character and `*` matches any sequence, using dynamic programming.", "def wildcard_matches(text, pattern):\n    previous = [True] + [False] * len(text)\n    for symbol in pattern:\n        current = [previous[0] and symbol == \"*\"]\n        for index, character in enumerate(text, 1):\n            if symbol == \"*\":\n                current.append(previous[index] or current[-1])\n            else:\n                current.append(previous[index - 1] and (symbol == \"?\" or symbol == character))\n        previous = current\n    return previous[-1]"),
    ("longest_palindrome", "Write a Python function that returns the earliest longest palindromic substring by expanding around every possible center.", "def longest_palindromic_substring(text):\n    best_start = best_end = 0\n    for center in range(len(text)):\n        for left, right in ((center, center), (center, center + 1)):\n            while left >= 0 and right < len(text) and text[left] == text[right]:\n                if right - left > best_end - best_start:\n                    best_start, best_end = left, right\n                left -= 1\n                right += 1\n    return text[best_start:best_end + 1]"),
    ("canonical_path", "Write a Python function that normalizes an absolute slash-separated path by removing empty and dot components and resolving double-dot components without moving above root.", "def canonical_absolute_path(path):\n    if not path.startswith(\"/\"):\n        raise ValueError(\"path must be absolute\")\n    components = []\n    for component in path.split(\"/\"):\n        if component in {\"\", \".\"}:\n            continue\n        if component == \"..\":\n            if components:\n                components.pop()\n        else:\n            components.append(component)\n    return \"/\" + \"/\".join(components)"),
    ("semantic_version_compare", "Write a Python function that compares two dot-separated nonnegative integer version strings after ignoring trailing zero components, returning -1, 0, or 1.", "def compare_versions(first, second):\n    left = [int(part) for part in first.split(\".\")]\n    right = [int(part) for part in second.split(\".\")]\n    width = max(len(left), len(right))\n    left.extend([0] * (width - len(left)))\n    right.extend([0] * (width - len(right)))\n    if left < right:\n        return -1\n    if left > right:\n        return 1\n    return 0"),
    ("query_string_parse", "Write a Python function that parses an ampersand-separated query string into a dictionary of key-to-list-of-values, treating fields without `=` as having an empty value.", "def parse_query_string(query):\n    result = {}\n    if not query:\n        return result\n    for field in query.split(\"&\"):\n        key, separator, value = field.partition(\"=\")\n        result.setdefault(key, []).append(value if separator else \"\")\n    return result"),
    ("table_pivot", "Write a Python function that pivots records containing row, column, and value fields into nested dictionaries and raises an error for duplicate row-column cells.", "def pivot_records(records):\n    result = {}\n    for record in records:\n        row = record[\"row\"]\n        column = record[\"column\"]\n        cells = result.setdefault(row, {})\n        if column in cells:\n            raise ValueError(\"duplicate pivot cell\")\n        cells[column] = record[\"value\"]\n    return result"),
    ("table_unpivot", "Write a Python function that converts nested row-to-column dictionaries into records with row, column, and value fields, preserving dictionary iteration order.", "def unpivot_table(table):\n    records = []\n    for row, columns in table.items():\n        for column, value in columns.items():\n            records.append({\"row\": row, \"column\": column, \"value\": value})\n    return records"),
    ("relational_left_join", "Write a Python function that left-joins records to indexed lookup records using configurable keys, returns one merged copy per match, and retains unmatched left records.", "def left_join_records(left_rows, right_rows, left_key, right_key):\n    index = {}\n    for row in right_rows:\n        index.setdefault(row[right_key], []).append(row)\n    result = []\n    for left in left_rows:\n        matches = index.get(left[left_key])\n        if not matches:\n            result.append(left.copy())\n            continue\n        for right in matches:\n            merged = left.copy()\n            merged.update(right)\n            result.append(merged)\n    return result"),
    ("dense_rank_groups", "Write a Python function that returns copied records with a dense rank field assigned within each group by descending score, giving equal scores equal ranks.", "def dense_rank_by_group(records):\n    grouped = {}\n    for record in records:\n        grouped.setdefault(record[\"group\"], []).append(record)\n    result = []\n    for rows in grouped.values():\n        previous_score = None\n        rank = 0\n        for record in sorted(rows, key=lambda row: row[\"score\"], reverse=True):\n            if previous_score is None or record[\"score\"] != previous_score:\n                rank += 1\n                previous_score = record[\"score\"]\n            copied = record.copy()\n            copied[\"rank\"] = rank\n            result.append(copied)\n    return result"),
    ("exponential_moving_average", "Write a Python function that returns the exponential moving average after every numeric value using a smoothing factor in the interval `(0, 1]`.", "def exponential_moving_averages(values, alpha):\n    if not 0 < alpha <= 1:\n        raise ValueError(\"alpha must be in (0, 1]\")\n    if not values:\n        return []\n    result = [values[0]]\n    for value in values[1:]:\n        result.append(alpha * value + (1 - alpha) * result[-1])\n    return result"),
    ("linear_missing_values", "Write a Python function that fills interior None values in a numeric sequence by linear interpolation between surrounding known values while leaving leading and trailing None values unchanged.", "def interpolate_missing_values(values):\n    result = list(values)\n    known = [index for index, value in enumerate(values) if value is not None]\n    for left_index, right_index in zip(known, known[1:]):\n        left_value = values[left_index]\n        right_value = values[right_index]\n        gap = right_index - left_index\n        for offset in range(1, gap):\n            result[left_index + offset] = left_value + (right_value - left_value) * offset / gap\n    return result"),
    ("interquartile_outliers", "Write a Python function that returns values strictly outside Tukey's 1.5-IQR fences, using medians of the lower and upper halves and preserving input order.", "def interquartile_outliers(values):\n    if len(values) < 4:\n        return []\n    ordered = sorted(values)\n    middle = len(ordered) // 2\n    lower = ordered[:middle]\n    upper = ordered[(len(ordered) + 1) // 2:]\n    def median(items):\n        center = len(items) // 2\n        return items[center] if len(items) % 2 else (items[center - 1] + items[center]) / 2\n    first_quartile = median(lower)\n    third_quartile = median(upper)\n    spread = third_quartile - first_quartile\n    low, high = first_quartile - 1.5 * spread, third_quartile + 1.5 * spread\n    return [value for value in values if value < low or value > high]"),
    ("linear_quantile", "Write a Python function that computes a quantile from a non-empty numeric sequence using linear interpolation between adjacent sorted values for a fraction from zero through one.", "def linear_quantile(values, fraction):\n    if not values or not 0 <= fraction <= 1:\n        raise ValueError(\"invalid values or fraction\")\n    ordered = sorted(values)\n    position = fraction * (len(ordered) - 1)\n    lower = int(position)\n    upper = min(lower + 1, len(ordered) - 1)\n    weight = position - lower\n    return ordered[lower] * (1 - weight) + ordered[upper] * weight"),
    ("median_sorted_sequences", "Write a Python function that returns the median of two ascending numeric sequences using a partition-based binary search and rejects two empty inputs.", "def median_of_sorted_sequences(first, second):\n    if len(first) > len(second):\n        first, second = second, first\n    if not second:\n        raise ValueError(\"at least one value is required\")\n    total = len(first) + len(second)\n    half = (total + 1) // 2\n    left, right = 0, len(first)\n    while left <= right:\n        first_cut = (left + right) // 2\n        second_cut = half - first_cut\n        first_left = float(\"-inf\") if first_cut == 0 else first[first_cut - 1]\n        first_right = float(\"inf\") if first_cut == len(first) else first[first_cut]\n        second_left = float(\"-inf\") if second_cut == 0 else second[second_cut - 1]\n        second_right = float(\"inf\") if second_cut == len(second) else second[second_cut]\n        if first_left <= second_right and second_left <= first_right:\n            if total % 2:\n                return max(first_left, second_left)\n            return (max(first_left, second_left) + min(first_right, second_right)) / 2\n        if first_left > second_right:\n            right = first_cut - 1\n        else:\n            left = first_cut + 1\n    raise ValueError(\"inputs must be sorted\")"),
    ("k_closest_values", "Write a Python function that returns the k values closest to a target ordered by distance, then value, then original position, without mutating the input.", "def k_closest_values(values, target, k):\n    if k < 0:\n        raise ValueError(\"k must be nonnegative\")\n    ranked = sorted(enumerate(values), key=lambda item: (abs(item[1] - target), item[1], item[0]))\n    return [value for _, value in ranked[:k]]"),
    ("quickselect", "Write a Python function that returns the zero-based kth smallest numeric value using iterative partitioning on a copied list and rejects an invalid index.", "def kth_smallest(values, k):\n    if not 0 <= k < len(values):\n        raise ValueError(\"invalid k\")\n    items = list(values)\n    left, right = 0, len(items) - 1\n    while True:\n        pivot = items[right]\n        boundary = left\n        for index in range(left, right):\n            if items[index] <= pivot:\n                items[boundary], items[index] = items[index], items[boundary]\n                boundary += 1\n        items[boundary], items[right] = items[right], items[boundary]\n        if boundary == k:\n            return items[boundary]\n        if boundary < k:\n            left = boundary + 1\n        else:\n            right = boundary - 1"),
    ("stable_counting_sort", "Write a Python function that stably sorts records by a nonnegative integer key bounded by a supplied maximum, returning copied records and rejecting out-of-range keys.", "def stable_counting_sort(records, key, maximum):\n    buckets = [[] for _ in range(maximum + 1)]\n    for record in records:\n        value = record[key]\n        if not 0 <= value <= maximum:\n            raise ValueError(\"key outside range\")\n        buckets[value].append(record.copy())\n    return [record for bucket in buckets for record in bucket]"),
    ("radix_sort", "Write a Python function that sorts nonnegative integers using stable least-significant-digit radix passes without mutating the input.", "def radix_sort_nonnegative(values):\n    if any(value < 0 for value in values):\n        raise ValueError(\"values must be nonnegative\")\n    result = list(values)\n    place = 1\n    maximum = max(result, default=0)\n    while maximum // place:\n        buckets = [[] for _ in range(10)]\n        for value in result:\n            buckets[(value // place) % 10].append(value)\n        result = [value for bucket in buckets for value in bucket]\n        place *= 10\n    return result"),
    ("inversion_count", "Write a Python function that counts index pairs appearing out of ascending order using merge-sort counting without mutating the sequence.", "def count_inversions(values):\n    def sort_count(items):\n        if len(items) < 2:\n            return items, 0\n        middle = len(items) // 2\n        left, left_count = sort_count(items[:middle])\n        right, right_count = sort_count(items[middle:])\n        merged = []\n        inversions = left_count + right_count\n        left_index = right_index = 0\n        while left_index < len(left) and right_index < len(right):\n            if left[left_index] <= right[right_index]:\n                merged.append(left[left_index])\n                left_index += 1\n            else:\n                merged.append(right[right_index])\n                right_index += 1\n                inversions += len(left) - left_index\n        return merged + left[left_index:] + right[right_index:], inversions\n    return sort_count(list(values))[1]"),
    ("stable_merge_sort", "Write a Python function that stably sorts a sequence by an optional key function using recursive merge sort and does not mutate the input.", "def stable_merge_sort(values, key=lambda value: value):\n    if len(values) < 2:\n        return list(values)\n    middle = len(values) // 2\n    left = stable_merge_sort(values[:middle], key)\n    right = stable_merge_sort(values[middle:], key)\n    merged = []\n    left_index = right_index = 0\n    while left_index < len(left) and right_index < len(right):\n        if key(left[left_index]) <= key(right[right_index]):\n            merged.append(left[left_index])\n            left_index += 1\n        else:\n            merged.append(right[right_index])\n            right_index += 1\n    return merged + left[left_index:] + right[right_index:]"),
    ("weighted_interval_schedule", "Write a Python function that returns the maximum total weight from mutually nonoverlapping half-open intervals using dynamic programming.", "def maximum_interval_weight(intervals):\n    ordered = sorted(intervals, key=lambda item: item[1])\n    ends = [end for _, end, _ in ordered]\n    best = [0]\n    for index, (start, _, weight) in enumerate(ordered):\n        left, right = 0, index\n        while left < right:\n            middle = (left + right) // 2\n            if ends[middle] <= start:\n                left = middle + 1\n            else:\n                right = middle\n        compatible = left if left < index and ends[left] <= start else left - 1\n        best.append(max(best[-1], weight + best[compatible + 1]))\n    return best[-1]"),
    ("dag_critical_path", "Write a Python function that returns the longest weighted path length from any source through a directed acyclic adjacency dictionary whose edges are `(neighbor, weight)` pairs.", "def dag_critical_path(graph):\n    nodes = set(graph)\n    indegree = {}\n    for node, edges in graph.items():\n        indegree.setdefault(node, 0)\n        for neighbor, _ in edges:\n            nodes.add(neighbor)\n            indegree[neighbor] = indegree.get(neighbor, 0) + 1\n    ready = [node for node in nodes if indegree.get(node, 0) == 0]\n    distance = {node: 0 for node in nodes}\n    processed = 0\n    while ready:\n        node = ready.pop()\n        processed += 1\n        for neighbor, weight in graph.get(node, []):\n            distance[neighbor] = max(distance[neighbor], distance[node] + weight)\n            indegree[neighbor] -= 1\n            if indegree[neighbor] == 0:\n                ready.append(neighbor)\n    if processed != len(nodes):\n        raise ValueError(\"graph contains a cycle\")\n    return max(distance.values(), default=0)"),
    ("maximum_flow", "Write a Python function that computes maximum flow from source to sink in a directed capacity dictionary using augmenting breadth-first paths without mutating capacities.", "def maximum_flow(capacities, source, sink):\n    residual = {}\n    for node, edges in capacities.items():\n        residual.setdefault(node, {})\n        for neighbor, capacity in edges.items():\n            residual[node][neighbor] = capacity\n            residual.setdefault(neighbor, {}).setdefault(node, 0)\n    total = 0\n    while True:\n        parent = {source: None}\n        queue = [source]\n        for node in queue:\n            for neighbor, capacity in residual.get(node, {}).items():\n                if capacity > 0 and neighbor not in parent:\n                    parent[neighbor] = node\n                    queue.append(neighbor)\n        if sink not in parent:\n            return total\n        amount = float(\"inf\")\n        node = sink\n        while parent[node] is not None:\n            amount = min(amount, residual[parent[node]][node])\n            node = parent[node]\n        node = sink\n        while parent[node] is not None:\n            previous = parent[node]\n            residual[previous][node] -= amount\n            residual[node][previous] += amount\n            node = previous\n        total += amount"),
    ("transitive_closure", "Write a Python function that returns the set of nodes reachable from every node in a directed adjacency dictionary, including neighbor-only nodes and excluding each node itself unless a cycle returns to it.", "def directed_transitive_closure(graph):\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    closure = {}\n    for start in nodes:\n        reached = set()\n        stack = list(graph.get(start, []))\n        while stack:\n            node = stack.pop()\n            if node in reached:\n                continue\n            reached.add(node)\n            stack.extend(graph.get(node, []))\n        closure[start] = reached\n    return closure"),
    ("edit_script", "Write a Python function that returns an insertion-and-deletion edit script transforming one sequence into another by tracing a longest-common-subsequence table.", "def insertion_deletion_script(first, second):\n    table = [[0] * (len(second) + 1) for _ in range(len(first) + 1)]\n    for left in range(len(first) - 1, -1, -1):\n        for right in range(len(second) - 1, -1, -1):\n            table[left][right] = 1 + table[left + 1][right + 1] if first[left] == second[right] else max(table[left + 1][right], table[left][right + 1])\n    script = []\n    left = right = 0\n    while left < len(first) or right < len(second):\n        if left < len(first) and right < len(second) and first[left] == second[right]:\n            script.append((\"keep\", first[left]))\n            left += 1\n            right += 1\n        elif right < len(second) and (left == len(first) or table[left][right + 1] >= table[left + 1][right]):\n            script.append((\"insert\", second[right]))\n            right += 1\n        else:\n            script.append((\"delete\", first[left]))\n            left += 1\n    return script"),
    ("checksum_modulus", "Write a Python function that computes a positional modular checksum for integer values using repeating positive weights and a positive modulus.", "def positional_checksum(values, weights, modulus):\n    if not weights or any(weight <= 0 for weight in weights) or modulus <= 0:\n        raise ValueError(\"invalid weights or modulus\")\n    return sum(value * weights[index % len(weights)] for index, value in enumerate(values)) % modulus"),
    ("rate_limit_windows", "Write a Python function that reports which ascending event timestamps are admitted by a sliding-window rate limit, allowing at most a supplied count in each positive-width interval.", "def sliding_window_admissions(timestamps, limit, width):\n    if limit < 0 or width <= 0:\n        raise ValueError(\"invalid limit or width\")\n    admitted = []\n    active = []\n    head = 0\n    for timestamp in timestamps:\n        while head < len(active) and active[head] <= timestamp - width:\n            head += 1\n        allowed = len(active) - head < limit\n        admitted.append(allowed)\n        if allowed:\n            active.append(timestamp)\n    return admitted"),
    ("token_bucket_simulation", "Write a Python function that reports admissions for ascending `(timestamp, cost)` requests under a token bucket with positive capacity and refill rate, starting full.", "def token_bucket_admissions(requests, capacity, refill_rate):\n    if capacity <= 0 or refill_rate < 0:\n        raise ValueError(\"invalid bucket settings\")\n    tokens = capacity\n    previous_time = requests[0][0] if requests else 0\n    result = []\n    for timestamp, cost in requests:\n        if timestamp < previous_time or cost < 0:\n            raise ValueError(\"invalid request sequence\")\n        tokens = min(capacity, tokens + (timestamp - previous_time) * refill_rate)\n        allowed = cost <= tokens\n        result.append(allowed)\n        if allowed:\n            tokens -= cost\n        previous_time = timestamp\n    return result"),
    ("deficit_round_robin", "Write a Python function that schedules queued `(item, cost)` entries across named queues using deficit round robin with a positive quantum and returns the service order.", "def deficit_round_robin(queues, quantum):\n    if quantum <= 0:\n        raise ValueError(\"quantum must be positive\")\n    pending = {name: list(items) for name, items in queues.items()}\n    deficits = {name: 0 for name in pending}\n    result = []\n    while any(pending.values()):\n        progressed = False\n        for name, items in pending.items():\n            if not items:\n                continue\n            deficits[name] += quantum\n            while items and items[0][1] <= deficits[name]:\n                item, cost = items.pop(0)\n                if cost < 0:\n                    raise ValueError(\"cost must be nonnegative\")\n                deficits[name] -= cost\n                result.append((name, item))\n                progressed = True\n        if not progressed and all(items and items[0][1] > deficits[name] + quantum for name, items in pending.items() if items):\n            continue\n    return result"),
    ("consistent_hash_assignment", "Write a Python function that assigns integer hash positions to the first clockwise node position on a sorted ring, wrapping to the first node, without mutating either sequence.", "def assign_hash_ring(positions, node_positions):\n    if not node_positions:\n        raise ValueError(\"ring must contain a node\")\n    ring = sorted(node_positions)\n    assignments = []\n    for position in positions:\n        left, right = 0, len(ring)\n        while left < right:\n            middle = (left + right) // 2\n            if ring[middle] < position:\n                left = middle + 1\n            else:\n                right = middle\n        assignments.append(ring[left] if left < len(ring) else ring[0])\n    return assignments"),
)
